//! The multi-node NUMA machine `--numa-nodes` asks QEMU to present.
//!
//! The guest's firmware description (a devicetree, or SRAT and SLIT
//! tables) is generated by QEMU from `-numa` options, so the kernel's
//! readers are exercised by describing the machine here and nothing
//! else. The machine is symmetric: every node holds the same share of
//! `-m` and of `-smp`, one socket per node, and the node count must
//! divide both so that no node is a different size by accident.

use std::fmt;

use super::GuestRamBacking;
use super::qemu::QemuOptions;
use super::qmp::{SizeError, parse_size};

/// The least distance QEMU and Linux's SLIT validation accept between
/// two different nodes: the ACPI SLIT `LOCAL_DISTANCE` is 10, and a
/// remote entry must be greater than it.
const MIN_REMOTE_DISTANCE: u8 = 11;

/// The greatest distance a SLIT entry can carry as a reachable node:
/// 255 is the ACPI "unreachable" marker.
const MAX_REMOTE_DISTANCE: u8 = 254;

/// Why `--numa-nodes` and `--numa-distance` do not describe a machine
/// QEMU can be asked for.
#[derive(Debug, thiserror::Error)]
pub(crate) enum NumaError {
    #[error("--numa-nodes must be at least 1; omit it for a machine without NUMA options")]
    ZeroNodes,
    #[error(
        "--numa-distance requires --numa-nodes (or `numa_nodes` in the config file): \
         the distance table describes the nodes it names"
    )]
    DistanceWithoutNodes,
    #[error(
        "--numa-distance has no pair to describe with --numa-nodes 1: a distance \
         joins two different nodes"
    )]
    DistanceWithOneNode,
    #[error(
        "--numa-distance {distance} is outside {MIN_REMOTE_DISTANCE}..={MAX_REMOTE_DISTANCE}: \
         the distance to the local node is 10, a remote node must be farther, and 255 \
         marks an unreachable node"
    )]
    DistanceOutOfRange { distance: u8 },
    #[error(
        "--numa-nodes {nodes} does not divide --smp {smp}: every node gets the same processors"
    )]
    NodesDoNotDivideSmp { nodes: u16, smp: u16 },
    #[error(
        "--numa-nodes {nodes} does not divide --memory {memory} ({bytes} bytes): every node \
         gets the same share of memory"
    )]
    NodesDoNotDivideMemory {
        nodes: u16,
        memory: String,
        bytes: u64,
    },
    #[error("--memory {memory} cannot be split across NUMA nodes: {source}")]
    Memory {
        memory: String,
        #[source]
        source: SizeError,
    },
}

/// A symmetric NUMA machine: `nodes` nodes of `cpus_per_node` processors
/// and `node_bytes` of memory each, one socket per node.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct NumaMachine {
    nodes: u16,
    cpus_per_node: u16,
    node_bytes: u64,
    distance: Option<u8>,
}

impl NumaMachine {
    /// Validates the two flags against the machine's `-smp` and `-m`.
    ///
    /// `None` is returned only when neither flag was given; any other
    /// combination is either a machine or an error.
    pub(crate) fn resolve(
        nodes: Option<u16>,
        distance: Option<u8>,
        smp: u16,
        memory: &str,
    ) -> Result<Option<Self>, NumaError> {
        let Some(nodes) = nodes else {
            return match distance {
                Some(_) => Err(NumaError::DistanceWithoutNodes),
                None => Ok(None),
            };
        };
        if nodes == 0 {
            return Err(NumaError::ZeroNodes);
        }
        if let Some(distance) = distance {
            if nodes == 1 {
                return Err(NumaError::DistanceWithOneNode);
            }
            if !(MIN_REMOTE_DISTANCE..=MAX_REMOTE_DISTANCE).contains(&distance) {
                return Err(NumaError::DistanceOutOfRange { distance });
            }
        }
        if !smp.is_multiple_of(nodes) {
            return Err(NumaError::NodesDoNotDivideSmp { nodes, smp });
        }
        let bytes = memory_bytes(memory)?;
        if bytes % u64::from(nodes) != 0 {
            return Err(NumaError::NodesDoNotDivideMemory {
                nodes,
                memory: memory.to_owned(),
                bytes,
            });
        }
        Ok(Some(Self {
            nodes,
            cpus_per_node: smp / nodes,
            node_bytes: bytes / u64::from(nodes),
            distance,
        }))
    }

    /// The `-smp` value: one socket per node, so a node's processors are
    /// one contiguous run of indexes, and no SMT.
    pub(crate) fn smp(&self) -> String {
        let total = u32::from(self.nodes) * u32::from(self.cpus_per_node);
        format!(
            "{total},sockets={},cores={},threads=1",
            self.nodes, self.cpus_per_node
        )
    }

    /// Every QEMU argument after `-smp`, in the order they are passed.
    ///
    /// The nodes' backends are the machine's whole RAM, so each is backed
    /// the way `backing` says.
    pub(crate) fn arguments(&self, backing: GuestRamBacking) -> Vec<String> {
        let mut arguments = Vec::new();
        for node in 0..self.nodes {
            let backend = backing.backend(backend_id(node), ByteSize(self.node_bytes));
            arguments.push("-object".to_owned());
            arguments.push(backend.to_string());
        }
        for node in 0..self.nodes {
            let mut options = QemuOptions::new("node");
            options
                .set("nodeid", node)
                .set("memdev", backend_id(node))
                .set("cpus", self.processors(node));
            arguments.push("-numa".to_owned());
            arguments.push(options.to_string());
        }
        if let Some(distance) = self.distance {
            for source in 0..self.nodes {
                for destination in (0..self.nodes).filter(|&other| other != source) {
                    let mut options = QemuOptions::new("dist");
                    options
                        .set("src", source)
                        .set("dst", destination)
                        .set("val", distance);
                    arguments.push("-numa".to_owned());
                    arguments.push(options.to_string());
                }
            }
        }
        arguments
    }

    /// The processor indexes of `node`, as `-numa node,cpus=` takes them.
    ///
    /// Processors are placed by index because that is the one form every
    /// machine accepts: `-numa cpu` names a topology property, and which
    /// one exists differs by machine (`socket-id` on `pc` and the Arm
    /// `virt`, only `core-id` on the RISC-V `virt`).
    fn processors(&self, node: u16) -> ProcessorRange {
        let first = u32::from(node) * u32::from(self.cpus_per_node);
        ProcessorRange {
            first,
            last: first + u32::from(self.cpus_per_node) - 1,
        }
    }
}

/// An inclusive run of processor indexes, a single index when it holds one.
struct ProcessorRange {
    first: u32,
    last: u32,
}

impl fmt::Display for ProcessorRange {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.first == self.last {
            write!(formatter, "{}", self.first)
        } else {
            write!(formatter, "{}-{}", self.first, self.last)
        }
    }
}

fn backend_id(node: u16) -> String {
    format!("helios-node{node}")
}

/// `-m`'s size in bytes. A bare number is mebibytes there, unlike the
/// bytes [`parse_size`] reads it as.
fn memory_bytes(memory: &str) -> Result<u64, NumaError> {
    let text = memory.trim();
    let sized = if text.ends_with(|c: char| c.is_ascii_digit()) {
        format!("{text}M")
    } else {
        text.to_owned()
    };
    parse_size(&sized).map_err(|source| NumaError::Memory {
        memory: memory.to_owned(),
        source,
    })
}

/// A byte count in the largest binary unit that holds it exactly.
struct ByteSize(u64);

impl fmt::Display for ByteSize {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        const UNITS: [(u64, &str); 3] = [(1 << 30, "G"), (1 << 20, "M"), (1 << 10, "K")];
        for (scale, suffix) in UNITS {
            if self.0.is_multiple_of(scale) {
                return write!(formatter, "{}{suffix}", self.0 / scale);
            }
        }
        write!(formatter, "{}", self.0)
    }
}

#[cfg(test)]
mod tests {
    use std::num::NonZeroUsize;

    use super::super::ResolvedGuestRam;
    use super::{GuestRamBacking, NumaError, NumaMachine};

    /// Anonymous guest RAM populated the way `guest_ram` says.
    fn anonymous(guest_ram: ResolvedGuestRam) -> GuestRamBacking {
        GuestRamBacking {
            shared_memfd: false,
            guest_ram,
        }
    }

    fn two_node(distance: Option<u8>) -> NumaMachine {
        NumaMachine::resolve(Some(2), distance, 4, "2G")
            .expect("two nodes divide four processors and 2G")
            .expect("a node count is a machine")
    }

    #[test]
    fn a_two_node_split_names_every_node_and_pair() {
        let machine = two_node(Some(20));
        assert_eq!(machine.smp(), "4,sockets=2,cores=2,threads=1");
        assert_eq!(
            machine.arguments(anonymous(ResolvedGuestRam::Lazy)),
            [
                "-object",
                "memory-backend-ram,id=helios-node0,size=1G",
                "-object",
                "memory-backend-ram,id=helios-node1,size=1G",
                "-numa",
                "node,nodeid=0,memdev=helios-node0,cpus=0-1",
                "-numa",
                "node,nodeid=1,memdev=helios-node1,cpus=2-3",
                "-numa",
                "dist,src=0,dst=1,val=20",
                "-numa",
                "dist,src=1,dst=0,val=20",
            ]
        );
    }

    #[test]
    fn no_distance_emits_no_table() {
        let machine = two_node(None);
        let arguments = machine.arguments(anonymous(ResolvedGuestRam::Lazy));
        assert!(
            arguments
                .iter()
                .all(|argument| !argument.starts_with("dist")),
            "{arguments:?}"
        );
    }

    #[test]
    fn three_nodes_emit_every_ordered_pair() {
        let machine = NumaMachine::resolve(Some(3), Some(30), 6, "3G")
            .expect("three nodes divide six processors and 3G")
            .expect("a node count is a machine");
        let pairs: Vec<_> = machine
            .arguments(anonymous(ResolvedGuestRam::Lazy))
            .into_iter()
            .filter(|argument| argument.starts_with("dist"))
            .collect();
        assert_eq!(pairs.len(), 6);
        assert!(pairs.contains(&"dist,src=2,dst=0,val=30".to_owned()));
    }

    #[test]
    fn a_bare_memory_size_is_mebibytes_as_qemu_reads_it() {
        let machine = NumaMachine::resolve(Some(2), None, 2, "1536")
            .expect("1536 MiB splits in two")
            .expect("a node count is a machine");
        assert!(
            machine
                .arguments(anonymous(ResolvedGuestRam::Lazy))
                .contains(&"memory-backend-ram,id=helios-node0,size=768M".to_owned())
        );
    }

    /// The node backends are the machine's whole RAM, so a preallocated
    /// backing is set on every one of them.
    #[test]
    fn preallocated_guest_ram_backs_every_node() {
        let guest_ram = ResolvedGuestRam::Prealloc {
            prealloc_threads: NonZeroUsize::new(8).expect("eight is non-zero"),
        };
        let backends: Vec<_> = two_node(None)
            .arguments(anonymous(guest_ram))
            .into_iter()
            .filter(|argument| argument.starts_with("memory-backend-ram"))
            .collect();
        assert_eq!(
            backends,
            [
                "memory-backend-ram,id=helios-node0,size=1G,prealloc=on,prealloc-threads=8",
                "memory-backend-ram,id=helios-node1,size=1G,prealloc=on,prealloc-threads=8",
            ]
        );
    }

    #[test]
    fn neither_flag_is_no_machine() {
        assert_eq!(NumaMachine::resolve(None, None, 4, "2G").unwrap(), None);
    }

    #[test]
    fn every_invalid_combination_is_refused_by_name() {
        assert!(matches!(
            NumaMachine::resolve(Some(0), None, 4, "2G"),
            Err(NumaError::ZeroNodes)
        ));
        assert!(matches!(
            NumaMachine::resolve(None, Some(20), 4, "2G"),
            Err(NumaError::DistanceWithoutNodes)
        ));
        assert!(matches!(
            NumaMachine::resolve(Some(1), Some(20), 4, "2G"),
            Err(NumaError::DistanceWithOneNode)
        ));
        for distance in [0, 10, 255] {
            assert!(matches!(
                NumaMachine::resolve(Some(2), Some(distance), 4, "2G"),
                Err(NumaError::DistanceOutOfRange { .. })
            ));
        }
        assert!(matches!(
            NumaMachine::resolve(Some(3), None, 4, "3G"),
            Err(NumaError::NodesDoNotDivideSmp { nodes: 3, smp: 4 })
        ));
        assert!(matches!(
            NumaMachine::resolve(Some(3), None, 6, "2G"),
            Err(NumaError::NodesDoNotDivideMemory { nodes: 3, .. })
        ));
        assert!(matches!(
            NumaMachine::resolve(Some(2), None, 4, "lots"),
            Err(NumaError::Memory { .. })
        ));
    }
}
